INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クローチェ", -470, 1.47, "2023/09/22 14:59:59", 2, "2023/06/30 12:00:00", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 0, 10001, 1, 1, 126401, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クローチェ", -470, 2.15, "2023/09/22 14:59:59", 1, "2023/06/30 12:00:00", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 0, 10002, 1, 2, 126401, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ライラエル", -470, 0, "2023/09/22 14:59:59", 2, "2023/06/30 12:00:00", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 0, 10003, 1, 1, 126501, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ライラエル", -470, 0, "2023/09/22 14:59:59", 1, "2023/06/30 12:00:00", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 0, 10004, 1, 2, 126501, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "リンド", -470, 0, "2023/12/22 14:59:59", 2, "2023/09/15 15:00:00", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 0, 10005, 2, 1, 127702, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "リンド", -470, 0, "2023/12/22 14:59:59", 2, "2023/09/15 15:00:00", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 0, 10006, 2, 2, 127702, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴルム", -470, 0, "2023/12/22 14:59:59", 1, "2023/09/15 15:00:00", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 0, 10007, 2, 1, 127802, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴルム", -470, 6.5, "2023/12/22 14:59:59", 1, "2023/09/15 15:00:00", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 0, 10008, 2, 2, 127802, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アネモネ", -470, 0, "2024/03/22 14:59:59", 1, "2023/12/15 15:00:00", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 0, 10009, 3, 1, 129602, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アネモネ", -470, 0, "2024/03/22 14:59:59", 1, "2023/12/15 15:00:00", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 0, 10010, 3, 2, 129602, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネフィ=ネラ", -470, 0, "2024/03/22 14:59:59", 1, "2023/12/15 15:00:00", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 0, 10011, 3, 1, 129701, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネフィ=ネラ", -470, 6.2, "2024/03/22 14:59:59", 1, "2023/12/15 15:00:00", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 0, 10012, 3, 2, 129701, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "カノン", -470, 3.1, "2024/06/22 14:59:59", 5, "2024/03/15 15:00:00", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 0, 10013, 4, 1, 130301, 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "カノン", -470, 6.15, "2024/06/22 14:59:59", 2, "2024/03/15 15:00:00", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 0, 10014, 4, 2, 130301, 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ナーナ", -470, 0, "2024/06/22 14:59:59", 2, "2024/03/15 15:00:00", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 0, 10015, 4, 1, 130401, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ナーナ", -470, 3.35, "2024/06/22 14:59:59", 1, "2024/03/15 15:00:00", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 0, 10016, 4, 2, 130401, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ホウオウ", -470, 0, "2024/09/22 14:59:59", 1, "2024/06/15 15:00:00", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 0, 10017, 5, 1, 130502, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ホウオウ", -470, 3.18, "2024/09/22 14:59:59", 1, "2024/06/15 15:00:00", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 0, 10018, 5, 2, 130502, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ホウオウ", -470, 0, "2024/09/22 14:59:59", 4, "2024/06/15 15:00:00", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 0, 10019, 5, 3, 130503, 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネア", -470, 4.9, "2024/09/22 14:59:59", 2, "2024/06/15 15:00:00", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 0, 10020, 5, 1, 123301, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネア", -470, 4.8, "2024/09/22 14:59:59", 2, "2024/06/15 15:00:00", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 0, 10021, 5, 2, 123301, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "カリザ", -470, 4.922, "2024/12/22 14:59:59", 1, "2024/09/15 15:00:00", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 0, 10022, 6, 1, 133301, 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "カリザ", -470, 9.638, "2024/12/22 14:59:59", 5, "2024/09/15 15:00:00", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 0, 10023, 6, 2, 133301, 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ミーア", -470, 2.88, "2024/12/22 14:59:59", 2, "2024/09/15 15:00:00", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 0, 10024, 6, 1, 133401, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ミーア", -470, 4.818, "2024/12/22 14:59:59", 1, "2024/09/15 15:00:00", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 0, 10025, 6, 2, 133401, 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "グレイス", -470, 1.78, "2025/03/22 14:59:59", 1, "2024/12/15 15:00:00", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 0, 10026, 7, 1, 133002, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "グレイス", -470, 6.15, "2025/03/22 14:59:59", 7, "2024/12/15 15:00:00", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 0, 10027, 7, 2, 133002, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴァイオレット", -470, 4.28, "2025/03/22 14:59:59", 2, "2024/12/15 15:00:00", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 0, 10028, 7, 1, 133102, 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴァイオレット", -470, 0, "2025/03/22 14:59:59", 1, "2024/12/15 15:00:00", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 0, 10029, 7, 2, 133102, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ルルィ", -470, 5.53, "2025/06/23 14:59:59", 1, "2025/03/15 15:00:00", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 0, 10030, 8, 1, 136902, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ルルィ", -470, 6.05, "2025/06/23 14:59:59", 7, "2025/03/15 15:00:00", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 0, 10031, 8, 2, 136902, 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "デュラン", -470, 0, "2025/06/23 14:59:59", 1, "2025/03/15 15:00:00", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 0, 10032, 8, 1, 137001, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "デュラン", -470, 0, "2025/06/23 14:59:59", 1, "2025/03/15 15:00:00", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 0, 10033, 8, 2, 137001, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "サツキ", -470, 0, "2025/09/23 14:59:59", 2, "2025/06/16 15:00:00", "おう\n好きなもん持ってきな", 0, 10034, 9, 1, 135902, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "サツキ", -470, 4.935, "2025/09/23 14:59:59", 6, "2025/06/16 15:00:00", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 0, 10035, 9, 2, 135902, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ユキノ", -470, 7.441, "2025/09/23 14:59:59", 5, "2025/06/16 15:00:00", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 0, 10036, 9, 1, 135802, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ユキノ", -470, 0, "2025/09/23 14:59:59", 7, "2025/06/16 15:00:00", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 0, 10037, 9, 2, 135802, 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クルル", -470, 2.295, "2025/12/22 14:59:59", 2, "2025/09/16 15:00:00", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 0, 10038, 10, 1, 130901, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クルル", -470, 6.281, "2025/12/22 14:59:59", 6, "2025/09/16 15:00:00", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 0, 10039, 10, 2, 130901, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴォルガーノ", -470, 5.549, "2025/12/22 14:59:59", 1, "2025/09/16 15:00:00", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 0, 10040, 10, 1, 137701, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴォルガーノ", -470, 2.64, "2025/12/22 14:59:59", 6, "2025/09/16 15:00:00", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 0, 10041, 10, 2, 137701, 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ライラエル", -470, 7.642, "2026/03/23 11:59:59", 4, "2025/12/15 15:00:00", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 0, 10042, 11, 1, 132801, 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ライラエル", -470, 0, "2026/03/23 11:59:59", 1, "2025/12/15 15:00:00", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 0, 10043, 11, 2, 132802, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クローチェ", -470, 0, "2026/03/23 11:59:59", 1, "2025/12/15 15:00:00", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 0, 10044, 11, 1, 134502, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クローチェ", -470, 3.72, "2026/03/23 11:59:59", 1, "2025/12/15 15:00:00", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 0, 10045, 11, 2, 134501, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネフィ＝ネラ", -470, 4.991, "2026/06/22 11:59:59", 1, "2026/03/16 12:00:00", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 0, 10046, 12, 1, 138201, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ネフィ＝ネラ", -470, 3.877, "2026/06/22 11:59:59", 4, "2026/03/16 12:00:00", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 0, 10047, 12, 2, 138201, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アラクネ", -470, 1.71, "2026/06/22 11:59:59", 6, "2026/03/16 12:00:00", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 0, 10048, 12, 1, 136001, 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アラクネ", -470, 5.32, "2026/06/22 11:59:59", 2, "2026/03/16 12:00:00", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 0, 10049, 12, 2, 136001, 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アネモネ", -470, 3.727, "2026/09/22 11:59:59", 4, "2026/06/15 12:00:00", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 0, 10050, 13, 1, 135401, 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "アネモネ", -470, 7.213, "2026/09/22 11:59:59", 9, "2026/06/15 12:00:00", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 0, 10051, 13, 2, 135401, 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クリア", -470, 1.874, "2026/09/22 11:59:59", 2, "2026/06/15 12:00:00", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 0, 10052, 13, 1, 135301, 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "クリア", -470, 0, "2026/09/22 11:59:59", 2, "2026/06/15 12:00:00", "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 0, 10053, 13, 2, 135301, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴァイオレット", -470, 4.215, "2026/12/22 11:59:59", 1, "2026/09/15 12:00:00", "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 0, 10054, 14, 1, 138001, 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "ヴァイオレット", -470, 0, "2026/12/22 11:59:59", 4, "2026/09/15 12:00:00", "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 0, 10055, 14, 2, 138001, 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "グレイス", -470, 5.477, "2026/12/22 11:59:59", 1, "2026/09/15 12:00:00", "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", 0, 10056, 14, 1, 138901, 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2002, "グレイス", -470, 5.743, "2026/12/22 11:59:59", 1, "2026/09/15 12:00:00", "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", 0, 10057, 14, 2, 138901, 2);
